import { balanceDue } from './payments.js';
import { daysBetween } from './dates.js';
import { lineTotal, lineDiscount, lineVAT } from './invoices.js';

/**
 * Generate an overdue invoices report.
 * Returns invoices with status 'issued' or 'partially_paid' whose dueDate is before asOf.
 * Sorted by most overdue first (oldest dueDate first).
 * @param {Array<{ number: string, customerId: string, status: string, dueDate: string, payments?: Array<{ amount: number, date: string }>, lines: Array, voucher?: { code: string, amount: number } }>} invoices
 * @param {string} asOf - YYYY-MM-DD format
 * @returns {Array<{ number: string, customerId: string, dueDate: string, daysOverdue: number, due: number }>}
 */
export function overdueInvoices(invoices, asOf) {
  return invoices
    .filter(inv => (inv.status === 'issued' || inv.status === 'partially_paid') && inv.dueDate < asOf)
    .map(inv => ({
      number: inv.number,
      customerId: inv.customerId,
      dueDate: inv.dueDate,
      daysOverdue: daysBetween(inv.dueDate, asOf),
      due: balanceDue(inv),
    }))
    .sort((a, b) => a.dueDate.localeCompare(b.dueDate));
}

/**
 * Generate a VAT summary report.
 * Returns VAT aggregated by rate over invoices with status 'issued', 'partially_paid', or 'paid'.
 * @param {Array<{ status: string, lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }> }>} invoices
 * @returns {Array<{ rate: number, base: number, vat: number }>}
 */
export function vatSummary(invoices) {
  const summary = new Map();

  for (const invoice of invoices) {
    if (invoice.status !== 'issued' && invoice.status !== 'partially_paid' && invoice.status !== 'paid') {
      continue;
    }

    for (const line of invoice.lines) {
      const rate = line.vatRate;
      const base = lineTotal(line) - lineDiscount(line);
      const vat = lineVAT(line);

      if (!summary.has(rate)) {
        summary.set(rate, { rate, base: 0, vat: 0 });
      }

      const entry = summary.get(rate);
      entry.base += base;
      entry.vat += vat;
    }
  }

  return Array.from(summary.values()).sort((a, b) => b.rate - a.rate);
}

