  const invoice1 = issueTestInvoice('C-001', '2026-10-01', 'NET30');
  const totals1 = invoiceTotals(invoice1);

  const result2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(result2.ok, true);
  const invoice2 = issueInvoice(result2.value, []);
  assert.equal(invoice2.ok, true);
  const totals2 = invoiceTotals(invoice2.value);

  const fee1 = lateFee(invoice1, '2026-11-10');
  const fee2 = lateFee(invoice2.value, '2026-11-10');

  const ratio = totals2.total / totals1.total;
  assert.equal(Math.round(fee2 / ratio), fee1);
});

test('lateFee handles large amounts', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'LOGO-PACK', qty: 10 }],
  });
  assert.equal(result.ok, true);
  const invoice = issueInvoice(result.value, []);
  assert.equal(invoice.ok, true);
  const fee = lateFee(invoice.value, '2026-11-10');
  assert(fee > 0);
});

test('lateFee rounds correctly to whole cents', () => {
  const invoice = issueTestInvoice('C-001', '2026-10-01', 'NET30');
  const fee = lateFee(invoice, '2026-11-02');
  assert.equal(fee, Math.round(fee));
});

test('lateFee with NET14 terms', () => {
  const invoice = issueTestInvoice('C-001', '2026-10-01', 'NET14');
  const totals = invoiceTotals(invoice);
  // Due: 2026-10-15, 10 days overdue on 2026-10-25
  const fee = lateFee(invoice, '2026-10-25');
  const expected = Math.round(totals.total * 0.04 / 100 * 10);
  assert.equal(fee, expected);
});

test('lateFee with EOM terms', () => {
  const invoice = issueTestInvoice('C-001', '2026-10-15', 'EOM');
  const totals = invoiceTotals(invoice);
  // Due: 2026-10-31, 5 days overdue on 2026-11-05
  const fee = lateFee(invoice, '2026-11-05');
  const expected = Math.round(totals.total * 0.04 / 100 * 5);
  assert.equal(fee, expected);
});

test('lateFee does not mutate the invoice', () => {
  const invoice = issueTestInvoice('C-001', '2026-10-01', 'NET30');
  const invoiceCopy = JSON.parse(JSON.stringify(invoice));
  lateFee(invoice, '2026-11-10');
  assert.deepEqual(invoice, invoiceCopy);
});

